// Generated by Skyramp v1.3.44 on 2026-09-12
// Scenario: /home/runner/work/eval-linkwarden/eval-linkwarden/apps/web/e2e/scenario_preferences_rejects_personal_access_token.json
//
// The PR states: "Adds preferences endpoint that rejects Bearer token auth. Only NextAuth
// session cookies accepted." A personal access token is therefore refused by
// GET /api/v1/users/me/preferences on EVERY transport — as an Authorization: Bearer header
// and as the identical token string in the next-auth.session-token cookie.
//
// This test is expected to FAIL on step 4 until the handler validates the credential TYPE
// instead of the header the credential arrived in: postToken.ts and createSession.ts both
// produce the same NextAuth JWT, so the current Authorization-header-only guard is bypassed
// by moving the token into a cookie. It turns green once the handler refuses a token whose
// accessToken record is not isSession.

// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    SESSION_COOKIE,
    createSession,
    createToken,
    getUserPreferences,
    getTokens,
    deleteToken,
} from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // Unique per run: POST /api/v1/tokens refuses a duplicate non-revoked token name.
    const sessionName = uniqueSuffix("skyramp-prefs-pat-session");
    const patName = uniqueSuffix("skyramp-prefs-pat");

    // Step 1 — a session, so the test can create a personal access token as the user.
    const sessionPostResponse = await createSession(client, URL_localhost, sessionName);

    expect(sessionPostResponse.statusCode, 'status code').toBe(200);

    const sessionToken = getResponseValue(sessionPostResponse, "response.token");
    expect(typeof sessionToken, 'session token is a string').toBe("string");

    const sessionAuth = {cookies: {[SESSION_COOKIE]: sessionToken}};

    // Step 2 — create a personal access token: the credential the PR says must be rejected.
    const tokensPostResponse = await createToken(client, URL_localhost, patName, sessionAuth, 200);

    expect(tokensPostResponse.statusCode, 'status code').toBe(200);

    const patSecretKey = getResponseValue(tokensPostResponse, "response.secretKey");
    const patId = getResponseValue(tokensPostResponse, "response.token.id");
    expect(typeof patSecretKey, 'personal access token secret is a string').toBe("string");
    expect(patSecretKey.length, 'personal access token secret is not empty').toBeGreaterThan(0);
    expect(getResponseValue(tokensPostResponse, "response.token.isSession"), 'the credential created is a personal access token, not a session').toBe(false);
    expect(getResponseValue(tokensPostResponse, "response.token.revoked"), 'the personal access token is live').toBe(false);
    expect(patId, 'personal access token has a real id').toBeGreaterThan(0);
    expect(getResponseValue(tokensPostResponse, "response.token.name"), 'the created token carries the name this test sent').toBe(patName);
    expect(getResponseValue(tokensPostResponse, "response.token.expires"), 'the created token carries an ISO expiry').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getResponseValue(tokensPostResponse, "response.token.token"), 'the created token is recorded by its jti')
        .toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);

    // Steps 3 and 4 run inside try/finally: the revocation below happens even when step 4
    // fails, so this test never leaves a live credential behind.
    try {
        // Step 3 — the personal access token in the Authorization header is refused.
        const preferencesGetResponse = await getUserPreferences(
            client,
            URL_localhost,
            {headers: {"Authorization": `Bearer ${patSecretKey}`}},
            401
        );

        expect(preferencesGetResponse.statusCode, 'status code').toBe(401);
        expect(getResponseValue(preferencesGetResponse, "response"), 'the Bearer transport is refused by name')
            .toBe("Bearer token authentication is not accepted for this endpoint. Use a session cookie.");
        expect(getResponseValue(preferencesGetResponse, "response.linksRouteTo"), 'no preference data leaks to a Bearer caller').toBeNull();

        // Step 4 — THE BEHAVIOUR UNDER TEST.
        // The SAME personal access token string, moved into the session cookie. The PR accepts
        // "Only NextAuth session cookies", so this non-session credential must be refused here too.
        const preferencesGet1Response = await getUserPreferences(
            client,
            URL_localhost,
            {cookies: {[SESSION_COOKIE]: patSecretKey}},
            401
        );

        expect(preferencesGet1Response.statusCode, 'a personal access token in the session cookie is refused').toBe(401);
        expect(getResponseValue(preferencesGet1Response, "response.linksRouteTo"), 'no preference data leaks to a personal access token').toBeNull();
        expect(getResponseValue(preferencesGet1Response, "response.theme"), 'no theme preference leaks to a personal access token').toBeNull();
        expect(getResponseValue(preferencesGet1Response, "response.id"), 'no user id leaks to a personal access token').toBeNull();
    } finally {
        // Step 5 — revoke the personal access token and the session this test created.
        const tokensTokensDeleteResponse = await deleteToken(client, URL_localhost, patId, sessionAuth, 200);

        expect(tokensTokensDeleteResponse.statusCode, 'status code').toBe(200);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.revoked"), 'the personal access token is revoked').toBe(true);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.id"), 'the revoked record is the token this test created').toBe(patId);

        expect(getResponseValue(tokensTokensDeleteResponse, "response.name"), 'the revoked record carries the name this test sent').toBe(patName);
        expect(getResponseValue(tokensTokensDeleteResponse, "response.isSession"), 'the revoked record is a personal access token, not a session').toBe(false);

        const sessionListResponse = await getTokens(client, URL_localhost, sessionAuth, 200);
        expect(sessionListResponse.statusCode, 'status code').toBe(200);
        const createdSession = getResponseValue(sessionListResponse, "response")
            ?.find((t: any) => t.name === sessionName);
        if (createdSession) {
            await deleteToken(client, URL_localhost, createdSession.id, sessionAuth, 200);
        }
    }
});
